import {referenceEnemies,combatTip} from './combat-tips.js';
import {presets,makePreset} from './presets.js';
import {classes,slots,names,quality,fresh,validate,calculate,itemStats,worlds,itemTier,resolveItem,autoAllocate,propertyValue} from './model.js';
const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#picker'),key='ligmarbd.hero.v1';let previousPresetBuild=null;let items=[],state=fresh(),currentSlot='weapon',selected=null,storageOK=true,catalogFilter='all';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(n).toLocaleString('ru-RU');const img=i=>`assets/${i.image_path}`;const icon=c=>`assets/icons/${c}.svg`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageOK=true}catch{storageOK=false;toast('Не удалось сохранить. Скачайте файл персонажа.')}}
function portrait(c,cls=''){return c.portrait?`<img class="hero-art ${cls}" src="assets/images/items/skins/${c.portrait}.webp" alt="${c.name}">`:`<div class="class-emblem ${cls}"><img src="${icon(Object.keys(classes).find(k=>classes[k]===c))}" alt="${c.name}"><span>${c.name}</span><small>Эмблема класса</small></div>`}
function top(){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===(location.hash||'#home')))}
function render(){top();document.title=location.hash==='#wardrobe'?'Раздевалка • LigmarBD':'Книга героев • LigmarBD';location.hash==='#wardrobe'?wardrobe():home()}
function home(){app.innerHTML=`<div class="page-title"><div><span class="eyebrow">ВАША КНИГА ПРИКЛЮЧЕНИЙ</span><h1>Каждый герой начинается с выбора</h1></div><span class="edition">МИР LIGMAR / 01</span></div><section class="home-main"><div class="hero-copy"><span class="eyebrow gold">МАСТЕРСКАЯ ПЕРСОНАЖА</span><h2>Собери свой<br>следующий билд</h2><p>Выбирай экипировку, распределяй характеристики и находи сочетания под свой стиль игры.</p><a class="primary" href="#wardrobe">Открыть раздевалку <span>↗</span></a><div class="hero-counts"><span><strong>6</strong> классов</span><span><strong>${items.length}</strong> предметов</span><span><strong>10</strong> слотов</span></div></div><div class="hero-scene">${portrait(classes.mage)}<div class="scene-label">Маг <span>Интеллект / Магический урон</span></div></div></section><section class="home-bottom"><div class="saved panel"><span class="eyebrow">ВАШ ПЕРСОНАЖ</span><div class="saved-line"><img src="${icon(state.classId)}" alt=""><div><h3>${esc(state.name)}</h3><p>${classes[state.classId].name} · ${state.level} уровень · ${Object.keys(state.equipment).length}/10 предметов</p></div><a class="secondary" href="#wardrobe">Продолжить →</a></div></div><div class="panel storage-note"><span class="small-symbol">◇</span><div><h3>Твой билд — под рукой</h3><p>Сохраняется в этом браузере. Файл персонажа можно скачать и перенести на другое устройство.</p></div></div></section><section class="roadmap"><h2>Другие страницы книги</h2><div class="roadmap-grid">${[['DPS-чек','Ротации и урон в бою','⚔'],['Механики','Формулы и правила игры','✧'],['Бестиарий','Противники и их особенности','♜'],['Библиотека','Чертежи и прогресс изучения','▤']].map(([a,b,c])=>`<article><span class="road-icon">${c}</span><h3>${a}</h3><p>${b}</p><small>В разработке</small></article>`).join('')}</div></section>`}
function statTierClass(e){const best=Math.max(0,...(e.props||[]).map(p=>p.percent));return best>=150?'tier-ancient':best>=100?'tier-perfect':''}
function slotHTML(slot){const e=state.equipment[slot],i=e&&resolveItem(items,e.id,e.quality);return `<button class="gear-slot ${e?.quality||'empty'}" data-slot="${slot}" aria-label="${slots[slot]}: ${i?esc(i.name.ru)+(e.quality==='legendary'?' · Легендарный':''):'выбрать предмет'}">${i?`<img src="${img(i)}" alt=""><span class="tier ${statTierClass(e)}">${({4:'IV',6:'VI',8:'VIII'})[itemTier(i,e.quality)]}</span>${e.enchant?`<b>+${e.enchant}</b>`:''}`:`<span class="empty-glyph">＋</span>`}<span class="slot-label">${slots[slot]}</span></button>`}
function wardrobe(){const c=classes[state.classId],r=calculate(state,items),left=['weapon','shoulders','neck','waist','finger'],right=['head','chest','hands','legs','feet'],free=20+5*state.level-Object.values(state.stats).reduce((a,b)=>a+b,0);app.innerHTML=`<div class="page-title"><div><span class="eyebrow">МАСТЕРСКАЯ ПЕРСОНАЖА</span><h1>Раздевалка</h1></div><div class="actions"><button id="export" class="secondary">↓ Скачать билд</button><button id="import" class="secondary">↑ Загрузить</button><input type="file" id="file" accept="application/json,.json" hidden></div></div><div class="world-switch" role="group" aria-label="Мир">${Object.entries(worlds).map(([id,w])=>`<button data-world="${id}" aria-pressed="${state.world===id}">${w.name}<small>${id==='zion'?'T4':'T6 / T8'} · до ${w.maxLevel} уровня</small></button>`).join('')}</div><section class="class-picker" aria-label="Класс персонажа">${Object.entries(classes).map(([id,c])=>`<button data-class="${id}" class="${id===state.classId?'selected':''}" aria-pressed="${id===state.classId}"><img src="${icon(id)}" alt=""><span>${c.name}</span></button>`).join('')}</section>${presetPanel()}<div class="wardrobe-layout"><section class="paperdoll panel"><div class="character-title"><div><input id="hero-name" aria-label="Имя персонажа" maxlength="60" value="${esc(state.name)}"><p>${c.caption}</p></div><label class="level-label">Уровень<input type="number" id="level" min="1" max="${worlds[state.world].maxLevel}" value="${state.level}"></label></div><div class="equipment-stage">${portrait(c)}<div class="slot-column left">${left.map(slotHTML).join('')}</div><div class="slot-column right">${right.map(slotHTML).join('')}</div><div class="character-pedestal">${c.name}<small>${Object.keys(state.equipment).length} из 10 предметов</small></div></div><div class="doll-foot"><span>${storageOK?'Сохранено на устройстве':'Сохранение недоступно'}</span><button class="text-button" id="clear">Снять всё</button></div></section><aside class="stats-column"><section class="panel"><div class="ribbon"><h2>Характеристики</h2><span>${free} свободных очков</span></div><div class="attributes">${['strength','dexterity','vitality','magic'].map(k=>`<label><span><span class="stat-help" tabindex="0" role="button" data-stat-help="${k}" aria-label="${names[k]}: влияние на параметры" aria-describedby="stat-tooltip">${names[k]} ⓘ</span><small>${r.gear[k]?`+${r.gear[k]} от вещей`:'Базовая характеристика'}</small></span><input type="number" data-stat="${k}" min="5" max="${state.stats[k]+free}" value="${state.stats[k]}" aria-label="${names[k]}"><strong>${r.stats[k]}</strong></label>`).join('')}</div><div class="auto-allocate"><button id="auto-stats" class="secondary wide">Распределить статы автоматически</button><p class="hint">Сначала требования вещей, затем приоритет класса. Перераспределяет все очки.${state.classId==='priest'?' Остаток: 80% в живучесть, 20% в интеллект.':''}</p></div></section><section class="panel"><div class="ribbon"><h2>Параметры героя</h2><span>С учётом экипировки</span></div><div class="combat-stats">${[[r.attackLabel,`${fmt(r.attack[0])}–${fmt(r.attack[1])}`,'attack'],['Защита',fmt(r.defense),''],['Сопротивление',fmt(r.resistance),''],['Уклонение',fmt(r.evasion),''],['Меткость',fmt(r.accuracy),''],['Шанс критического удара',r.crit+'%',''],['Время активации',r.activation+'%',''],[r.hp===null?'Прибавка к HP':'Здоровье',r.hp===null?'+'+fmt(r.hpBonus):fmt(r.hp),'health'],[r.mana===null?'Прибавка к мане':'Мана',r.mana===null?'+'+fmt(r.manaBonus):fmt(r.mana),'mana']].map(([k,v,cl],index)=>`<div class="${cl}"><span class="stat-help" tabindex="0" role="button" data-combat-help="${['attack','defense','resistance','evasion','accuracy','crit','activation','health','mana'][index]}" aria-describedby="stat-tooltip">${k} ⓘ</span><strong>${v}</strong></div>`).join('')}</div><p class="hint">Базовый урон — до умения, крита и защиты противника.</p></section><details class="panel settings"><summary>Баффы и исходные параметры</summary><div class="settings-grid">${Object.entries({attack:'Бафф атаки, %',passive:'Пассивка атаки, %',defense:'Бафф защиты, %',resistance:'Бафф сопротивления, %',evasion:'Бафф уклонения, %',hp:'Бафф здоровья, %'}).map(([k,n])=>`<label>${n}<input data-buff="${k}" type="number" min="0" max="500" value="${state.buffs[k]}"></label>`).join('')}<label>HP при 5 живучести, без вещей<input id="baseHP" type="number" min="0" placeholder="Не задано" value="${state.baseHP??''}"></label><label>Мана при 5 интеллекта, без вещей<input id="baseMana" type="number" min="0" placeholder="Не задано" value="${state.baseMana??''}"></label></div><p class="hint">Без исходных HP и маны показаны только прибавки. Бафф атаки здесь меняет AttackMultiplier; отдельный урон баффа мага не включён.</p></details>${r.warnings.length?`<details class="panel warnings" open><summary>Не выполнены требования (${r.warnings.length})</summary><ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul><p>Параметры показаны для планирования. Такой набор пока нельзя надеть в игре.</p></details>`:''}</aside></div><details class="calculation-notes panel"><summary>Что учитывает эта версия</summary><p>Базы предметов, качество по рабочей модели ×1 / 1,1 / 1,2 / 1,3, заточка по новой таблице +1…+12 и до трёх дополнительных свойств. Камни пока не учитываются. Значение допсвойств вычисляется как минимум + (максимум − минимум) × процент / 100.</p><p>Базы каталога требуют сверки после обновлений. Модель качества проверена для нескольких предметов T6; для T4 её применение предварительное. Округление до ближайшего целого; для половин пока используется округление вверх. Требования проверяются ориентировочно с итоговыми статами, порядок надевания не моделируется. Изображение героя — иллюстрация и не меняется от выбранных вещей.</p></details>`;bindWardrobe();bindLiveInputs();bindStatTips(r)}
function bindWardrobe(){document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{try{const next=makePreset(state,items,b.dataset.preset,'high');const before=structuredClone(state);state=next;previousPresetBuild=before;save();wardrobe();toast('Сборка надета, очки распределены')}catch(err){toast(err.message)}});if($('#undo-preset'))$('#undo-preset').onclick=()=>{state=previousPresetBuild;previousPresetBuild=null;save();wardrobe()};$('#auto-stats').onclick=()=>{try{const stats=autoAllocate(state,items,presets[state.buildPreset]?.classId===state.classId?presets[state.buildPreset].stat:null);state.stats=stats;save();wardrobe();toast('Статы распределены')}catch(err){toast(err.message)}};document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{const world=b.dataset.world;if(world===state.world)return;try{localStorage.setItem(key+'.'+state.world,JSON.stringify(state));const saved=localStorage.getItem(key+'.'+world);const next=saved?validate(JSON.parse(saved),items):{...fresh(state.classId),world,level:worlds[world].maxLevel,name:state.name};state=next;save();wardrobe()}catch{toast('Не удалось переключить мир. Скачайте текущий билд.')}});document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{if(state.classId!==b.dataset.class){state.baseHP=null;state.baseMana=null}state.classId=b.dataset.class;const e=state.equipment.weapon;if(e&&!classes[state.classId].weapons.includes(items.find(i=>i.template_id===e.id).item_subtype))delete state.equipment.weapon;save();wardrobe()});document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>openSlot(b.dataset.slot));$('#hero-name').onchange=e=>{state.name=e.target.value.trim()||'Новый герой';save()};$('#level').onchange=e=>{const n=+e.target.value;if(!Number.isInteger(n)||n<1||n>worlds[state.world].maxLevel){wardrobe();return}if(state.level!==n){state.baseHP=null;state.baseMana=null}state.level=n;if(Object.values(state.stats).reduce((a,b)=>a+b,0)>20+5*n){state.stats={strength:5,dexterity:5,vitality:5,magic:5};toast('Очки сброшены под новый уровень')}save();wardrobe()};document.querySelectorAll('[data-stat]').forEach(e=>e.onchange=()=>{const n=+e.value,k=e.dataset.stat,budget=20+5*state.level-Object.entries(state.stats).filter(([x])=>x!==k).reduce((a,[,b])=>a+b,0);if(Number.isInteger(n)&&n>=5&&n<=budget)state.stats[k]=n;else toast('Не хватает свободных очков');save();wardrobe()});document.querySelectorAll('[data-buff]').forEach(e=>e.onchange=()=>{state.buffs[e.dataset.buff]=Math.max(0,Math.min(500,+e.value||0));save();wardrobe()});for(const k of ['baseHP','baseMana'])$('#'+k).onchange=e=>{state[k]=e.target.value===''?null:Math.max(0,Math.min(1000000,+e.target.value||0));save();wardrobe()};$('#clear').onclick=()=>{if(!Object.keys(state.equipment).length)return; if(confirm('Снять все предметы с персонажа?')){state.equipment={};save();wardrobe()}};$('#export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='ligmar-character.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('Файл слишком большой');const candidate=validate(JSON.parse(await f.text()),items);state=candidate;save();wardrobe();toast('Персонаж загружен')}catch(err){toast(err.message)}}}
function openSlot(slot){currentSlot=slot;selected=null;$('#picker-slot').textContent=slots[slot];const e=state.equipment[slot];if(e)configure(e.id);else listItems();dialog.showModal()}
function listItems(){
 $('#picker-title').textContent='Выбор предмета';
 const list=items.filter(i=>i.item_type===currentSlot&&i.item_tier===worlds[state.world].tier&&!i.blueprint_quality&&(currentSlot!=='weapon'||classes[state.classId].weapons.includes(i.item_subtype)));
 const order={magic:0,light:1,heavy:2};list.sort((a,b)=>(order[a.item_subtype]??3)-(order[b.item_subtype]??3));
 $('#picker-body').innerHTML=`<p class="hint">${worlds[state.world].name} · выберите тип и качество предмета</p><div class="rarity-grid">${list.map(i=>`<div class="rarity-row">${Object.entries(quality).map(([q,v])=>{const variant=q==='legendary'?items.find(x=>x.item_type===i.item_type&&x.item_subtype===i.item_subtype&&x.item_tier===i.item_tier&&x.blueprint_quality==='legendary')||i:i;return `<button class="rarity-card ${q}" data-item="${variant.template_id}" data-quality="${q}" aria-label="${esc(i.name.ru)} — ${v.name}"><small>T${itemTier(i,q)} · ${v.name}</small><img src="${img(i)}" alt=""><strong>${esc(i.name.ru)}</strong></button>`}).join('')}</div>`).join('')||'<p>Нет подходящих предметов.</p>'}</div>`;
 document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>configure(b.dataset.item,b.dataset.quality));
}
function configure(id,chosenQuality){const previous=state.equipment[currentSlot];const i=resolveItem(items,id,chosenQuality||(previous?.id===id?previous.quality:undefined));selected=i;let draft=previous?.id===id?structuredClone(previous):{id,quality:i.blueprint_quality==='legendary'?'legendary':'epic',enchant:0,props:[]};if(chosenQuality)draft.quality=chosenQuality;$('#picker-title').textContent=i.name.ru;$('#picker-body').innerHTML=`<button class="text-button" id="back-list">← Заменить предмет</button><div class="item-config ${draft.quality==='legendary'?'legendary-config':''}"><div class="config-icon-wrap"><img class="config-icon" src="${img(i)}" alt=""><span id="config-tier" class="tier ${statTierClass(draft)}">${({4:'IV',6:'VI',8:'VIII'})[itemTier(i,draft.quality)]}</span></div><div><span class="eyebrow">T${itemTier(i,draft.quality)} / ${slots[currentSlot]}</span><h3>${esc(i.name.ru)}</h3><div id="item-primary" class="item-primary"></div><p>${i.blueprint_quality==='legendary'?'Легендарный чертёж · собственные диапазоны допсвойств':'Выбери параметры экземпляра'}</p></div></div><div class="config-fields"><label>Качество<select id="quality" disabled>${Object.entries(quality).map(([k,v])=>`<option value="${k}" ${draft.quality===k?'selected':''}>${v.name}</option>`).join('')}</select></label><label>Заточка<select id="enchant">${Array.from({length:13},(_,n)=>`<option value="${n}" ${draft.enchant===n?'selected':''}>+${n}</option>`).join('')}</select></label></div><h3>Дополнительные свойства</h3><p class="hint">Значение = минимум + (максимум − минимум) × процент / 100.</p><div class="property-rows">${[0,1,2].map(n=>`<div><select data-prop="${n}" aria-label="Свойство ${n+1}"><option value="">Без свойства</option>${Object.entries(i.property_value_ranges).map(([k])=>`<option value="${k}" ${draft.props[n]?.key===k?'selected':''}>${names[k]||k}</option>`).join('')}</select><select data-percent="${n}" aria-label="Сила свойства ${n+1}">${[90,100,150].map(v=>`<option value="${v}" ${(draft.props[n]?.percent||90)===v?'selected':''}>${v}%</option>`).join('')}</select><output class="property-value" data-prop-value="${n}" aria-live="polite"></output></div>`).join('')}</div><div class="item-preview" id="item-preview"></div><button id="equip" class="primary wide">${previous?.id===id?'Сохранить изменения':'Надеть предмет'}</button>${previous?'<button class="text-button remove-item" id="remove-item">Снять предмет</button>':''}`;const read=()=>{draft.quality=$('#quality').value;draft.enchant=+$('#enchant').value;draft.props=[...document.querySelectorAll('[data-prop]')].filter(e=>e.value).map(e=>({key:e.value,percent:+document.querySelector(`[data-percent="${e.dataset.prop}"]`).value}));return draft};function preview(){read();$('#config-tier').className='tier '+statTierClass(draft);for(const field of document.querySelectorAll('[data-prop]')){const output=document.querySelector(`[data-prop-value="${field.dataset.prop}"]`),range=i.property_value_ranges[field.value];field.parentElement.classList.remove('property-perfect','property-ancient');if(!range){output.innerHTML='';output.hidden=true;continue}output.hidden=false;const percent=+document.querySelector(`[data-percent="${field.dataset.prop}"]`).value,current=propertyValue(range,percent),unit=['activationTime','criticalHitRate','requirements','physicalDamageReduction'].includes(field.value)?'%':'';const value=n=>n.toLocaleString('ru-RU',{maximumFractionDigits:6})+unit;field.parentElement.classList.toggle('property-perfect',percent>=100&&percent<150);field.parentElement.classList.toggle('property-ancient',percent>=150);output.setAttribute('aria-label',`Текущее значение: ${value(current)}; диапазон: ${value(range.min)}–${value(range.max)}${percent>=150?'; древнее свойство':''}`);output.innerHTML=`<b class="${percent>=150?'ancient-value':''}">${value(current)}</b><span title="Диапазон свойства">[${value(range.min)}–${value(range.max)}]</span>`}document.querySelector('.item-config').classList.toggle('legendary-config',draft.quality==='legendary');const values=itemStats(i,draft),primary=new Set(Object.keys(i.base_stats).filter(k=>!k.endsWith('Interval')));const primaryRows=[];for(const k of primary){if(k.endsWith('AttackMax'))continue;if(k.endsWith('AttackMin')){const prefix=k.slice(0,-3);primaryRows.push(`<span><b>${fmt(values[k])}–${fmt(values[prefix+'Max'])}</b> ${prefix==='magicAttack'?'Маг. атака':'Физ. атака'}</span>`)}else primaryRows.push(`<span><b>${fmt(values[k])}</b> ${names[k]||k}</span>`)}$('#item-primary').innerHTML=primaryRows.join('');$('#item-preview').innerHTML=Object.entries(values).filter(([k])=>!k.endsWith('Interval')&&!primary.has(k)).map(([k,v])=>`<span>${names[k]||k}<b>${fmt(v)}</b></span>`).join('');$('#item-preview').hidden=!$('#item-preview').innerHTML}$('#back-list').onclick=()=>{$('#picker-title').textContent='Выбор предмета';selected=null;listItems()};document.querySelectorAll('.config-fields select,.property-rows select').forEach(e=>e.onchange=preview);$('#equip').onclick=()=>{read();if(new Set(draft.props.map(p=>p.key)).size!==draft.props.length){toast('Выберите разные дополнительные свойства');return}state.equipment[currentSlot]=draft;save();dialog.close();wardrobe();toast('Предмет надет')};if($('#remove-item'))$('#remove-item').onclick=()=>{delete state.equipment[currentSlot];save();dialog.close();wardrobe()};preview()}
$('#close-picker').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close()}});window.onhashchange=render;
try{const response=await fetch('data/library.json');if(!response.ok)throw Error('Каталог недоступен');items=(await response.json()).blueprints;try{const saved=localStorage.getItem(key);if(saved)state=validate(JSON.parse(saved),items)}catch{toast('Сохранение не удалось прочитать. Можно загрузить резервный файл.')}render();if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'get_character_build',description:'Прочитать текущий билд и вычисленные параметры без изменений.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({character:structuredClone(state),result:calculate(state,items)})})).catch(()=>{})}}catch(err){app.innerHTML='<section class="panel load-error"><h1>Не удалось открыть каталог</h1><p>Обновите страницу. Для запуска нужен локальный сервер.</p><button onclick="location.reload()">Повторить</button></section>'}

let inputTimer;
function bindLiveInputs(){
 document.querySelectorAll('main input[type="number"]').forEach(el=>{
  el.oninput=()=>{clearTimeout(inputTimer);inputTimer=setTimeout(()=>{
   if(!el.isConnected)return;
   const selector=el.id?'#'+el.id:el.dataset.stat?'[data-stat="'+el.dataset.stat+'"]':'[data-buff="'+el.dataset.buff+'"]';
   const focused=document.activeElement===el;
   const opened=[...document.querySelectorAll('details[open]')].map(x=>x.className);
   el.onchange?.({target:el});
   for(const d of document.querySelectorAll('details'))if(opened.includes(d.className))d.open=true;
   if(focused)document.querySelector(selector)?.focus();
  },300)};
 });
 $('#hero-name').oninput=$('#hero-name').onchange;
}

function statTipContent(k,r){
 const c=classes[state.classId],v=r.stats[k],n=x=>Number(x.toFixed(2)).toLocaleString('ru-RU');
 const rows=[];const add=(text,formula)=>rows.push([text,formula]);
 const attack=(who,div)=>add(`Урон ${who}: +${n(v/div*100)}% к множителю атаки${c.stat===k?'':' (у текущего класса не действует)'}.`,`Множитель атаки = 1 + ${names[k]} / ${div} + пассивки + баффы. Действует у ${who}.`);
 const defense=(type,other)=>{const isVit=k==='vitality',sum=isVit?2*v+3*r.stats[other]:3*v+2*r.stats.vitality;
 add(`${type}: вклад в усиление экипировки ≈ +${n(v*(isVit?.08:.12))}% до округления; вместе со вторым статом +${Math.round(sum/25)}%. Также растёт плоская база.`,`${type}: база = округл((Живучесть + ${type==='Защита'?'Сила':'Интеллект'} − 2) / 4); усиление вещей = округл((2 × Живучесть + 3 × ${type==='Защита'?'Сила':'Интеллект'}) / 25)%. Баффы прибавляются к усилению.`)};
 if(k==='strength'){attack('воина и стража',150);defense('Защита','vitality')}
 if(k==='dexterity'){
  attack('лучника и убийцы',150);
  add(`Уклонение: +${n(c.evasion*v)} ед. до баффов; +${c.evasion} за очко.`,`Уклонение = округл((1 + ${c.evasion} × Ловкость + уклонение вещей) × (1 + баффы / 100)).`);
  add(`Крит: +${Math.floor(v/20)} п.п. к шансу. До следующего процента: ${20-v%20} ловкости.`,`Шанс крита = 1% + целая часть(Ловкость / 20)% + бонусы вещей; максимум 100%.`);
  add(`Меткость: +${n(c.accuracy*v)} ед.; +${c.accuracy} за очко.`,`Меткость = 1 + ${c.accuracy} × Ловкость + меткость вещей.`);
 }
 if(k==='magic'){
  attack('мага и жреца',100);
  const bonus=(v-5)*c.mana;
  add(`Мана: +${n(bonus)} ед. сверх базовых 5 интеллекта; +${c.mana} за очко.${state.baseMana>0?' Это +'+n(bonus/state.baseMana*100)+'% к исходной мане.':''}`,`Мана = исходная при 5 интеллекта + (Интеллект − 5) × ${c.mana} + мана вещей.`);
  defense('Сопротивление','vitality');
 }
 if(k==='vitality'){
  const bonus=(v-5)*c.hp;
  add(`HP: +${n(bonus)} ед. сверх базовых 5 живучести, до баффов; +${c.hp} за очко.${state.baseHP>0?' Это +'+n(bonus/state.baseHP*100)+'% к исходным HP.':''}`,`HP = округл((исходные HP при 5 живучести + (Живучесть − 5) × ${c.hp} + HP вещей) × (1 + бафф HP / 100)).`);
  defense('Защита','strength');defense('Сопротивление','magic');
 }
 return `<strong>${names[k]}: ${v}</strong><small>С учётом вещей · ${c.name}</small><div class="tip-values">${rows.map(a=>`<p>${a[0]}</p>`).join('')}<small>Проценты атаки — слагаемые множителя, а не прирост итогового урона. Шанс уклонения зависит от меткости врага.</small></div><div class="tip-formulas">${rows.map(a=>`<p>${a[1]}</p>`).join('')}</div><footer>Удерживайте Alt — упрощённые формулы</footer>`;
}
function bindStatTips(r){
 let tip=document.querySelector('#stat-tooltip');if(!tip){tip=document.createElement('div');tip.id='stat-tooltip';tip.role='tooltip';document.body.append(tip)}tip.hidden=true;
 const hide=()=>{tip.hidden=true};
 const enemies=referenceEnemies(items);
 for(const el of document.querySelectorAll('[data-stat-help],[data-combat-help]')){
  const show=()=>{tip.innerHTML=el.dataset.combatHelp?combatTipContent(el.dataset.combatHelp,r,enemies):statTipContent(el.dataset.statHelp,r);tip.hidden=false;const b=el.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(b.left,innerWidth-tip.offsetWidth-8))+'px';tip.style.top=Math.max(8,Math.min(b.bottom+8,innerHeight-tip.offsetHeight-8))+'px'};
  el.onmouseenter=show;el.onmouseleave=()=>{if(document.activeElement!==el)hide()};el.onfocus=show;el.onblur=hide;
  el.onclick=e=>{e.preventDefault();show()};el.onkeydown=e=>{if(e.key==='Escape'){hide();el.blur()}if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}};
 }
 window.addEventListener('scroll',hide,{once:true});
}
window.addEventListener('keydown',e=>{if(e.key==='Alt')document.documentElement.classList.add('show-stat-formulas');if(e.key==='Escape'){const t=document.querySelector('#stat-tooltip');if(t)t.hidden=true}});
window.addEventListener('keyup',e=>{if(e.key==='Alt')document.documentElement.classList.remove('show-stat-formulas')});
window.addEventListener('blur',()=>{document.documentElement.classList.remove('show-stat-formulas');const t=document.querySelector('#stat-tooltip');if(t)t.hidden=true});

function presetPanel(){
 const list=Object.entries(presets).filter(([,p])=>p.classId===state.classId);
 if(!list.length)return '';
 return `<section class="panel preset-panel"><div class="preset-heading"><h2>Готовые сборки</h2><span class="hint">Хай тир · эпики · +8/+5 · 100/90/90%</span></div><div class="preset-buttons">${list.map(([id,p])=>`<button class="secondary" data-preset="${id}">${p.name}</button>`).join('')}${previousPresetBuild?'<button class="text-button" id="undo-preset">Отменить автоодевание</button>':''}</div><p class="hint">Заменяет всю экипировку и распределяет очки. Камни пока не добавляются.</p>${list.map(([,p])=>`<p class="hint"><b>${p.name}:</b> ${p.note}</p>`).join('')}${state.buildPreset&&presets[state.buildPreset]?.classId===state.classId?`<p class="hint">Время активации текущей сборки: ${calculate(state,items).activation}% от обычного времени каста.</p>`:''}</section>`;
}

function combatTipContent(key,r,enemies){
 const {title,rows}=combatTip(key,state,r,enemies);
 return `<strong>${title}</strong><small>Эталон: лучник · Острог · 55 уровень · хай тир · без баффов и камней${state.world==='zion'?' · сравнение без синхронизации миров':''}</small><div class="tip-values">${rows.map(a=>`<p>${a[0]}</p>`).join('')}</div><div class="tip-formulas">${rows.map(a=>`<p>${a[1]}</p>`).join('')}</div><footer>Удерживайте Alt — упрощённые формулы</footer>`;
}
